agent-browser eval "JSON.stringify(['.view_be26877b3f639fb1_0_group', '.concat_1_concat_0_group', '.concat_1_concat_1_group'].map(sel => {
  const el = document.querySelector(sel);
  if (!el) return { selector: sel, found: false };
  const rects = Array.from(el.querySelectorAll('rect'));
  const paths = Array.from(el.querySelectorAll('path'));
  const circles = Array.from(el.querySelectorAll('circle'));
  return {
    selector: sel,
    found: true,
    rects: rects.length,
    paths: paths.length,
    circles: circles.length,
    // let's get some rect heights/y coords
    rectHeights: rects.map(r => ({ height: r.getAttribute('height'), width: r.getAttribute('width'), x: r.getAttribute('x'), y: r.getAttribute('y') }))
  };
}))"
